begin;
select set_config('scheduleqa.owner',gen_random_uuid()::text,true),set_config('scheduleqa.other',gen_random_uuid()::text,true),set_config('scheduleqa.space',gen_random_uuid()::text,true),set_config('scheduleqa.draft',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(current_setting('scheduleqa.owner')::uuid,'schedule-owner@example.invalid',now(),false),(current_setting('scheduleqa.other')::uuid,'schedule-other@example.invalid',now(),false);
select public.access_testing_set(true,true);
select public.geofence_save_with_invitations(current_setting('scheduleqa.owner')::uuid,current_setting('scheduleqa.space')::uuid,jsonb_build_object('name','Scheduled QA','description','Public description','latitude',30.2672,'longitude',-97.7431,'diameter',500,'starts_at',now()+interval '1 hour','ends_at',now()+interval '2 hours'),array['schedule-guest@example.invalid']);
select public.geofence_save_draft(current_setting('scheduleqa.owner')::uuid,current_setting('scheduleqa.draft')::uuid,'{"name":"Unpaid draft","description":"Private","latitude":30.2672,"longitude":-97.7431,"diameter":500}');
select public.access_testing_grant('geofence',current_setting('scheduleqa.owner')::uuid,current_setting('scheduleqa.space')::uuid);
do $$declare sid uuid:=current_setting('scheduleqa.space')::uuid;j geofence_private.email_jobs;c jsonb;begin
 assert not public.geofence_active(sid),'Future chat must be closed';
 assert exists(select 1 from geofence_private.email_jobs where space_id=sid and kind='invitation'),'Future invitations send after creation, before the event';
 update geofence_private.email_jobs set lease_id=gen_random_uuid(),lease_until=now()+interval '5 minutes',state='processing' where space_id=sid and kind='invitation' returning * into j;
 c:=public.geofence_mail_context(j.id,j.lease_id);assert c->>'startsAt' is not null and c->>'email'='schedule-guest@example.invalid';
 begin perform public.geofence_schedule_set(current_setting('scheduleqa.other')::uuid,sid,null,null);raise exception 'Wrong owner edited schedule';exception when sqlstate 'PT404' then null;end;
 begin perform public.geofence_schedule_set(current_setting('scheduleqa.owner')::uuid,sid,now(),now());raise exception 'Invalid schedule accepted';exception when sqlstate 'PT422' then null;end;
 assert (select starts_at>now() from geofence_private.spaces where id=sid),'Invalid update must preserve schedule';
end $$;
set local role anon;
do $$declare sid uuid:=current_setting('scheduleqa.space')::uuid;r jsonb;begin
 assert not has_function_privilege(current_user,'public.geofence_schedule_set(uuid,uuid,timestamptz,timestamptz)','execute');
 assert not has_schema_privilege(current_user,'geofence_private','usage');
 r:=public.geofence_read(sid);assert r->>'name'='Scheduled QA' and (r->>'active')::boolean=false,'Invited guests can see future times';
 assert not exists(select 1 from jsonb_array_elements(public.geofence_map()->'circles') c where c->>'id' in (sid::text,current_setting('scheduleqa.draft'))),'No future chats or unpaid drafts on map';
end $$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('scheduleqa.other'),'is_anonymous',false)::text,true);
set local role authenticated;
do $$begin begin perform public.geofence_chat_v2(current_setting('scheduleqa.space')::uuid,30.2672,-97.7431,5,clock_timestamp());raise exception 'Chat opened early';exception when sqlstate 'PT410' then null;end;end $$;
reset role;
select public.geofence_schedule_set(current_setting('scheduleqa.owner')::uuid,current_setting('scheduleqa.space')::uuid,now(),now()+interval '1 hour');
do $$begin assert public.geofence_active(current_setting('scheduleqa.space')::uuid),'Start is inclusive';end $$;
set local role anon;
do $$declare r jsonb;begin
 select c into r from jsonb_array_elements(public.geofence_map()->'circles') c where c->>'id'=current_setting('scheduleqa.space');
 assert r is not null and r->>'activeUntil' is not null;
 assert not(r ?| array['owner_id','email','recipient','paidUntil','subscription_id','customer_id']),'Map exposes only public circle content';
end $$;
reset role;
set local role authenticated;
select public.geofence_chat_v2(current_setting('scheduleqa.space')::uuid,30.2672,-97.7431,5,clock_timestamp(),p_name=>'Schedule QA');
reset role;
select public.geofence_schedule_set(current_setting('scheduleqa.owner')::uuid,current_setting('scheduleqa.space')::uuid,now()-interval '1 hour',now());
do $$begin
 assert not public.geofence_active(current_setting('scheduleqa.space')::uuid),'End is exclusive';
 assert not exists(select 1 from geofence_private.people where space_id=current_setting('scheduleqa.space')::uuid),'Closing a window removes current presence';
 assert exists(select 1 from geofence_private.conversations where space_id=current_setting('scheduleqa.space')::uuid and ended_at is not null),'Closing ends the conversation';
end $$;
set local role authenticated;
do $$begin begin perform public.geofence_chat_v2(current_setting('scheduleqa.space')::uuid,30.2672,-97.7431,5,clock_timestamp());raise exception 'Chat stayed open after end';exception when sqlstate 'PT410' then null;end;end $$;
reset role;
select public.geofence_schedule_set(current_setting('scheduleqa.owner')::uuid,current_setting('scheduleqa.space')::uuid,null,null);
do $$begin assert public.geofence_active(current_setting('scheduleqa.space')::uuid),'Existing always-active behavior remains available';end $$;
select public.access_testing_set(false,false);
do $$begin assert not public.geofence_active(current_setting('scheduleqa.space')::uuid),'Schedule never grants billing access';end $$;
insert into geofence_private.billing(mode,space_id,status,pro_until) values('test',current_setting('scheduleqa.space')::uuid,'active',now()+interval '1 day');
do $$begin assert not public.geofence_active(current_setting('scheduleqa.space')::uuid),'Test subscriptions cannot publish circles';end $$;
insert into geofence_private.billing(mode,space_id,status,pro_until) values('live',current_setting('scheduleqa.space')::uuid,'active',now()+interval '1 day');
do $$begin assert public.geofence_active(current_setting('scheduleqa.space')::uuid);end $$;
update geofence_private.billing set pro_until=now()-interval '1 second' where mode='live' and space_id=current_setting('scheduleqa.space')::uuid;
do $$begin assert not public.geofence_active(current_setting('scheduleqa.space')::uuid),'Expired subscription closes chat regardless of schedule';end $$;
rollback;
